import assert from "node:assert/strict";
import { mkdtempSync, readdirSync, readFileSync, rmSync } from "node:fs";
import { createServer } from "node:http";
import type { AddressInfo } from "node:net";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test, type TestContext } from "node:test";
import { decideStatus, EventError, parseEvent, processEvent } from "../src/refunds.ts";
import { buildApp } from "../src/server.ts";
import { Store } from "../src/store.ts";
import { computeSignature, SignatureError, verifyReplay, verifyWebhook } from "../src/verify.ts";

const SECRET = "whsec_test_pay381";
const POLICY = JSON.parse(readFileSync(new URL("../config/refunds.json", import.meta.url), "utf8"));
const NOW = 1731920000;

function event(event_id: string, type = "refund.requested", data: Record<string, unknown> = {}) {
  return { event_id, type, created: NOW,
    data: { refund_id: "rf_test", payment_id: "pay_test", amount: 500000, currency: "INR", ...data } };
}

function signed(body: string | Buffer, timestamp = Math.floor(Date.now() / 1000), secret = SECRET) {
  return { "paygate-signature": `t=${timestamp},v1=${computeSignature(secret, timestamp, body)}` };
}

function replay(body: string | Buffer, timestamp = Math.floor(Date.now() / 1000), secret = SECRET) {
  return { "x-replay-timestamp": String(timestamp),
    "x-replay-signature": `v1=${computeSignature(secret, timestamp, body)}` };
}

function snapshot(dir: string): Record<string, string> {
  return Object.fromEntries(readdirSync(dir, { recursive: true, withFileTypes: true })
    .filter((entry) => entry.isFile())
    .map((entry) => {
      const path = join(entry.parentPath, entry.name);
      return [path.slice(dir.length), readFileSync(path).toString("base64")];
    }));
}

async function fixture(t: TestContext) {
  const dir = mkdtempSync(join(tmpdir(), "pay381-"));
  const store = new Store(dir);
  const app = buildApp(store, { roles: {}, principals: {} }, POLICY,
    { webhook_secrets: ["retired-secret", SECRET], tolerance_s: 300, replay_tolerance_s: 86400 });
  const server = createServer((req, res) => void app(req, res));
  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
  t.after(async () => {
    await new Promise<void>((resolve, reject) => server.close((err) => err ? reject(err) : resolve()));
    rmSync(dir, { recursive: true, force: true });
  });
  const url = `http://127.0.0.1:${(server.address() as AddressInfo).port}/webhooks/paygate`;
  return { dir, store, post: (body: string | Buffer, headers: Record<string, string> = {}) =>
    fetch(url, { method: "POST", headers, body }) };
