test("signature rotation accepts any matching signature/secret, without normalising the body", () => {
  const body = '{ "unicode": "₹", "n": 1 }\n';
  const header = `t=${NOW},v1=${"0".repeat(64)},v1=${computeSignature(SECRET, NOW, body)}`;
  assert.doesNotThrow(() => verifyWebhook(body, header, ["old", SECRET], NOW));
  assert.throws(() => verifyWebhook(JSON.stringify(JSON.parse(body)), header, [SECRET], NOW), SignatureError);
  assert.throws(() => verifyWebhook(body, header, [], NOW), SignatureError);
  const bytes = Buffer.from([0x7b, 0xff, 0x7d]);
  assert.doesNotThrow(() => verifyWebhook(bytes, signed(bytes, NOW)["paygate-signature"], [SECRET], NOW));
  assert.throws(() => verifyWebhook(bytes.toString("utf8"), signed(bytes, NOW)["paygate-signature"], [SECRET], NOW), SignatureError);
});

test("signature tolerance is inclusive and rejects stale or future deliveries", () => {
  for (const offset of [-301, -300, 300, 301]) {
    const header = signed("{}", NOW + offset)["paygate-signature"];
    const verify = () => verifyWebhook("{}", header, [SECRET], NOW);
    if (Math.abs(offset) <= 300) assert.doesNotThrow(verify);
    else assert.throws(verify, SignatureError);
  }
  for (const header of [undefined, "", `v1=${"0".repeat(64)}`, `t=${NOW}`, `t=${NOW},v1=bad`,
    `t=${NOW},t=${NOW},v1=${"0".repeat(64)}`, `t=Infinity,v1=${"0".repeat(64)}`]) {
    assert.throws(() => verifyWebhook("{}", header, [SECRET], NOW), SignatureError);
  }
});

test("replay verification supports rotation and enforces both timestamp boundaries", () => {
