    const verify = () => verifyReplay("{}", String(timestamp), header, ["old", SECRET], NOW);
    if (Math.abs(offset) <= 300) assert.doesNotThrow(verify);
    else assert.throws(verify, SignatureError);
  }
});

test("configured policy uses Dana's inclusive INR 5000 threshold", () => {
