test("invalid signatures, including replay bypass attempts, leave all state untouched", async (t) => {
  const { dir, store, post } = await fixture(t);
  const body = JSON.stringify(event("evt_bad_auth"));
  const now = Math.floor(Date.now() / 1000);
  const before = snapshot(dir);
  const attempts = [
    {}, signed(body, now, "wrong"), signed(body, now - 3600), signed(body, now + 3600),
    { ...signed(body), "x-replay-timestamp": String(now) },
    { ...signed(body), ...replay(body, now, "wrong") },
    { ...signed(body), ...replay(body, now - 3600) },
    { ...signed(body), ...replay(body, now + 3600) },
    { ...signed(body), ...replay(body), "x-replay-timestamp": "not-a-timestamp" },
    { ...signed(body), ...replay(body), "x-replay-timestamp": "" },
    { ...signed(body), ...replay(body), "x-replay-signature": "v1=bad" },
  ];
  for (const headers of attempts) {
    assert.equal((await post(body, headers)).status, 401, JSON.stringify(headers));
    assert.deepEqual(snapshot(dir), before);
    assert.equal(store.isProcessed("evt_bad_auth"), false);
  }
  assert.equal((await post(body + " ", signed(body))).status, 401);
  assert.deepEqual(snapshot(dir), before);
});

test("valid replay ignores the original signature and deduplicates normal and replay deliveries", async (t) => {
  const { dir, store, post } = await fixture(t);
  const body = JSON.stringify(event("evt_replay"), null, 2) + "\n";
  const original = Math.floor(Date.now() / 1000) - 7200;
  const first = await post(body, { ...signed(body, original), ...replay(body) });
  assert.equal(first.status, 200);
  assert.deepEqual(await first.json(), { received: true, duplicate: false });
  const before = snapshot(dir);
  for (const headers of [signed(body), replay(body), { ...replay(body), "paygate-signature": "invalid" }]) {
    const res = await post(body, headers);
    assert.equal(res.status, 200);
    assert.deepEqual(await res.json(), { received: true, duplicate: true });
    assert.deepEqual(snapshot(dir), before);
  }
