  const res = await post(reformatted, signed(reformatted));
  assert.deepEqual(await res.json(), { received: true, duplicate: true });
  assert.deepEqual(snapshot(dir), before);
  assert.equal(store.listRefunds().length, 1);
  assert.equal(new Store(dir).isProcessed("evt_replay"), true);
  const other = JSON.stringify(event("evt_no_original"));
  assert.equal((await post(other, replay(other))).status, 200);
});

test("signed invalid events return 400 without storing or processing them", async (t) => {
  const { dir, post } = await fixture(t);
  const before = snapshot(dir);
  const invalid = ["{", "null", "[]", "{}", JSON.stringify({ ...event("bad_created"), created: "yesterday" }),
    JSON.stringify(event("bad_amount", "refund.requested", { amount: -1 })),
    JSON.stringify(event("bad_fraction", "refund.requested", { amount: 1.5 })),
    JSON.stringify(event("bad_currency", "refund.requested", { currency: null })),
    JSON.stringify(event("bad_refund_id", "refund.cancelled", { refund_id: "" }))];
  for (const body of invalid) {
    assert.equal((await post(body, signed(body))).status, 400, body);
    assert.deepEqual(snapshot(dir), before);
  }
});

test("unhandled types are acknowledged and deduplicated without refunds or audits", async (t) => {
  const { dir, store, post } = await fixture(t);
  const body = JSON.stringify({ event_id: "evt_unknown", type: "payment.updated", created: NOW });
  const first = await post(body, signed(body));
  assert.equal(first.status, 200);
  assert.deepEqual(await first.json(), { received: true, duplicate: false });
  assert.deepEqual(store.listRefunds(), []);
  const before = snapshot(dir);
  const second = await post(body, signed(body));
  assert.deepEqual(await second.json(), { received: true, duplicate: true });
  assert.deepEqual(snapshot(dir), before);
  assert.ok(!Object.keys(before).some((name) => name.endsWith("audit.jsonl")));
});

test("simultaneous deliveries create and audit a refund only once", async (t) => {
  const { dir, store, post } = await fixture(t);
  const body = JSON.stringify(event("evt_concurrent"));
  const responses = await Promise.all(Array.from({ length: 8 }, () => post(body, signed(body))));
  for (const res of responses) assert.equal(res.status, 200);
  const results = await Promise.all(responses.map((res) => res.json()));
  assert.equal(results.filter((result) => !result.duplicate).length, 1);
  assert.equal(store.listRefunds().length, 1);
  assert.equal(readFileSync(join(dir, "audit.jsonl"), "utf8").trim().split("\n").length, 1);
});
